#include "espscreen/protocol/frame.hpp"
#include <array>
#include <cstring>
namespace espscreen::protocol {namespace {constexpr std::size_t HEADER=12;void put16(std::uint8_t* p,std::uint16_t v){p[0]=v&0xff;p[1]=v>>8;}void put32(std::uint8_t* p,std::uint32_t v){for(int i=0;i<4;++i)p[i]=(v>>(8*i))&0xff;}std::uint16_t get16(const std::uint8_t* p){return p[0]|(p[1]<<8);}std::uint32_t get32(const std::uint8_t* p){return p[0]|(p[1]<<8)|(p[2]<<16)|(p[3]<<24);} }
std::uint32_t crc32(std::span<const std::uint8_t> bytes){std::uint32_t crc=0xffffffffu;for(auto b:bytes){crc^=b;for(int i=0;i<8;++i)crc=(crc>>1)^(0xedb88320u&static_cast<std::uint32_t>(-(static_cast<int>(crc&1))));}return ~crc;}
CodecResult encode_frame(const FrameView& f,std::span<std::uint8_t> output,bool delimiter){if(f.payload.size()>kMaxPayload)return {{core::ErrorCode::invalid_argument,"payload too large"},0};std::array<std::uint8_t,HEADER+kMaxPayload+4> raw{};put16(raw.data(),kMagic);raw[2]=kVersion;raw[3]=static_cast<std::uint8_t>(f.type);put32(raw.data()+4,f.request_id);put16(raw.data()+8,static_cast<std::uint16_t>(f.payload.size()));raw[10]=raw[11]=0;std::memcpy(raw.data()+HEADER,f.payload.data(),f.payload.size());const auto crc=crc32(std::span<const std::uint8_t>(raw.data(),HEADER+f.payload.size()));put32(raw.data()+HEADER+f.payload.size(),crc);const std::size_t reserve=delimiter?1:0;if(output.size()<reserve)return {{core::ErrorCode::capacity_exceeded,"frame output too small"},0};auto r=cobs_encode(std::span<const std::uint8_t>(raw.data(),HEADER+f.payload.size()+4),output.first(output.size()-reserve));if(!r.status)return r;if(delimiter){if(r.bytes>=output.size())return {{core::ErrorCode::capacity_exceeded,"frame delimiter does not fit"},0};output[r.bytes++]=0;}return r;}
core::Status decode_frame(std::span<const std::uint8_t> encoded,MutableFrame& out){if(!encoded.empty()&&encoded.back()==0)encoded=encoded.first(encoded.size()-1);std::array<std::uint8_t,HEADER+kMaxPayload+4> raw{};auto r=cobs_decode(encoded,raw);if(!r.status)return r.status;if(r.bytes<HEADER+4)return {core::ErrorCode::corrupt,"frame too short"};if(get16(raw.data())!=kMagic||raw[2]!=kVersion)return {core::ErrorCode::corrupt,"frame magic or version mismatch"};const auto size=get16(raw.data()+8);if(size>kMaxPayload||r.bytes!=HEADER+size+4)return {core::ErrorCode::corrupt,"frame length mismatch"};const auto expected=get32(raw.data()+HEADER+size);if(crc32(std::span<const std::uint8_t>(raw.data(),HEADER+size))!=expected)return {core::ErrorCode::corrupt,"frame crc mismatch"};out.type=static_cast<MessageType>(raw[3]);out.request_id=get32(raw.data()+4);out.payload_size=size;std::memcpy(out.payload.data(),raw.data()+HEADER,size);return core::Status::success();}
}
